// The My Child phase docs (2026-10-13): lib/data/pp_phase_docs.dart,
// generated by tools/phase_pages/docx_to_dart.py from the user's PH001–PH015.
// The user: "the document is the source of truth".
//
// Holds: every phase is complete and in the doc's shape; no builder note
// reached a parent; the docs win on the parenting screens (name, at a glance,
// the snapshot cards, the phase and milestone pages, the doctor lines); the
// activities join Today with the child's own phase first; and it is wired.
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:parentveda/data/pp_phase_docs.dart';
import 'package:parentveda/screens/post_pregnancy/development_activity_screen.dart';
import 'package:parentveda/screens/post_pregnancy/pp_grow_data.dart';
import 'package:parentveda/screens/post_pregnancy/pp_home_changes.dart';
import 'package:parentveda/screens/post_pregnancy/pp_phase_doc_activities.dart';
import 'package:parentveda/screens/post_pregnancy/pp_phase_doc_reads.dart';
import 'package:parentveda/screens/post_pregnancy/phase_detail_screen.dart';
import 'package:parentveda/screens/post_pregnancy/pp_phases_data.dart';

/// Every string a parent can see in a doc.
List<String> _strings(PpPhaseDoc d) => [
      d.name, ...d.hero, ...d.doctor,
      for (final c in d.living) ...[c.title, c.body, ...c.tips],
      for (final s in d.snapshot) ...[s.title, s.line],
      for (final m in d.milestones) ...[
        m.title, m.typicalAge, m.summary, m.whatIsIt, m.whyItMatters, m.insight,
        ...m.ways, ...m.activities, ...m.relatedTopics, ...m.doctor,
      ],
      for (final a in d.activities) ...[
        a.title, a.intro, ...a.builds, a.why, ...a.need, ...a.steps, ...a.remember,
        ...a.safe, a.variations, ...a.linked,
      ],
    ];

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  group('the docs', () {
    test('phases 1 to 15, each named as its doc', () {
      expect(kPpPhaseDocs.keys.toList()..sort(), [for (var i = 1; i <= 15; i++) i]);
      expect(ppPhaseDocFor(1)!.name, 'The Settling In');
      expect(ppPhaseDocFor(4)!.name, 'Finding a Rhythm');
      expect(ppPhaseDocFor(10)!.name, 'Showing and Sharing', reason: '"(9 months)" is the file name, not the phase');
      expect(ppPhaseDocFor(15)!.name, 'Big Feelings');
      expect(ppPhaseDocFor(16), isNull);
    });

    test('every phase is the doc shape', () {
      for (final d in kPpPhaseDocList) {
        final w = d.code;
        expect(d.hero.length, inInclusiveRange(4, 6), reason: w);
        expect(d.living.length, inInclusiveRange(4, 6), reason: w);
        for (final c in d.living) {
          expect(c.body, isNotEmpty, reason: '$w ${c.title}');
          expect(c.tips, isNotEmpty, reason: '$w ${c.title}');
        }
        expect(d.snapshot.map((s) => s.domain), PpDocDomain.values, reason: '$w: five fixed domains, fixed order');
        expect(d.doctor.length, greaterThanOrEqualTo(3), reason: w);
        expect(d.milestones.map((m) => m.domain), PpDocDomain.values, reason: w);
        for (final m in d.milestones) {
          for (final s in [m.summary, m.whatIsIt, m.whyItMatters, m.insight]) {
            expect(s, isNotEmpty, reason: '$w ${m.title}');
          }
          expect(m.ways, isNotEmpty, reason: '$w ${m.title}');
          expect(m.doctor, isNotEmpty, reason: '$w ${m.title}');
        }
        expect(d.activities.length, greaterThanOrEqualTo(4), reason: w);
        for (final a in d.activities) {
          expect(a.steps, isNotEmpty, reason: '$w ${a.title}');
          expect(a.safe, isNotEmpty, reason: '$w ${a.title}');
        }
      }
    });

    test('no builder note, annotation, emoji or probability reached a parent', () {
      final notes = RegExp(
          r'Change log|\bwords?\)|target \d|sign-off|Page components|Panel to|✓|\(MS\d|\(ACT\d|\bACT\d{3}|'
          r'\bMS\d{3}|\(PH\d|renamed|unchanged|\(revised|Revision \d|Status:|I would |— primary|optional, secondary|'
          r'Card \d —|&amp;|&apos;|— note:|Why I changed|Flag Summary|Important:|parent-facing');
      final emoji = RegExp('[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]', unicode: true);
      final odds = RegExp(r'your\s+(child.s|baby.s)?\s*(chance|chances|probability|odds)', caseSensitive: false);
      for (final d in kPpPhaseDocList) {
        for (final s in _strings(d)) {
          expect(notes.hasMatch(s), isFalse, reason: '${d.code}: "$s"');
          expect(emoji.hasMatch(s), isFalse, reason: '${d.code}: "$s"');
          expect(odds.hasMatch(s), isFalse, reason: '${d.code}: "$s"');
          expect(s, s.trim(), reason: '${d.code}: untrimmed "$s"');
        }
      }
    });

    test('lines broken mid-sentence in the docs read whole', () {
      final ph7 = ppPhaseDocFor(7)!;
      expect(ph7.snapshot[2].line, contains('"ba-ba" or "da-da"'));
      expect(ph7.living.first.title, 'Starting First Foods', reason: 'a title glued to its text is split');
      expect(ppPhaseDocFor(4)!.snapshot.first.title, 'Finding Hands and Feet');
    });
  });

  group('the doc wins on the parenting screens', () {
    test('the phase carries the doc name, hero, living titles, snapshot and doctor lines', () {
      final p = ppPhaseWithDoc(kPhasesAuthored.first);
      final d = ppPhaseDocFor(1)!;
      expect(p.name, 'The Settling In');
      expect(p.summary, d.hero.first);
      expect(p.workingOn, [for (final c in d.living) c.title]);
      expect(p.milestones.map((m) => m.text), [for (final s in d.snapshot) s.title]);
      final doctor = p.sections.singleWhere((s) => s.heading == 'When to call the doctor');
      expect(doctor.paragraphs, d.doctor);
      // The docs are the only phase text (the user, 2026-10-14): nothing
      // authored rides along. Was: Feeding now / Sleep now and the India note kept.
      expect(p.sections.map((s) => s.heading), ['When to call the doctor']);
      expect(p.tagline, isEmpty);
      expect(p.reassurance, isEmpty);
      expect(p.indianNote, isNull);
      expect(p.screeningNote, isNull);
      expect(p.checkpoint, isFalse);
    });

    test('a phase with no doc yet says its guide is being written, and nothing authored', () {
      // Was: 'phases 16 to 20 are untouched' (the authored phase in full).
      for (final a in kPhasesAuthored.where((x) => ppPhaseDocFor(x.number) == null)) {
        final p = ppPhaseWithDoc(a);
        expect(p.name, a.name, reason: 'phase ${a.number} keeps its name');
        expect(p.ageLabel, a.ageLabel);
        expect(p.summary, kPhaseGuideComing);
        expect(p.workingOn, isEmpty);
        expect(p.milestones, isEmpty);
        // Only the route to a doctor stays until the doc brings its own.
        expect(p.sections.map((s) => s.heading), ['When to call the doctor'], reason: 'phase ${a.number}');
        expect(p.reassurance, isEmpty);
        expect(p.indianNote, isNull);
        expect(phaseAwaitingDoc(p), isTrue);
      }
    });

    test('"How your baby is doing" is the doc\'s five, in its words', () {
      final phase = ppPhaseWithDoc(kPhasesAuthored[2]);
      final changes = phaseChangesFor(phase);
      final d = ppPhaseDocFor(3)!;
      expect(changes.map((c) => c.category), ['Brain', 'Physical', 'Language', 'Emotional', 'Nutrition']);
      expect(changes.map((c) => c.title), [for (final s in d.snapshot) s.title]);
      expect(changes.first.notice, d.snapshot.first.line);
      expect(changes.every((c) => c.milestonePage != null), isTrue);
    });

    test('the phase page reads in the doc order; the milestone page too', () {
      final d = ppPhaseDocFor(1)!;
      final read = ppPhaseDocAsRead(d, ppPhaseWithDoc(kPhasesAuthored.first));
      expect(read.title.en, 'The Settling In');
      expect(read.teaser.en, d.hero.first);
      final headings = [for (final s in read.sections) s.heading?.en];
      final living = headings.indexOf('Living through this phase');
      final snapshot = headings.indexOf('Child snapshot');
      expect(living, greaterThan(0));
      expect(snapshot, greaterThan(living + d.living.length - 1));
      expect(read.sections[snapshot].custom, isA<PpDocSnapshotBlock>());
      expect(read.whenToSeeSomeone.body.en, d.doctor.join('\n'));

      final m = ppMilestoneAsRead(d, d.milestones.first);
      expect(m.title.en, 'Focusing on Faces');
      expect([for (final s in m.sections) s.heading?.en].whereType<String>(),
          containsAllInOrder(['What is it?', 'Why it matters', 'Ways to support']));
      final act = m.sections.map((s) => s.custom).whereType<PpDocActivityBlock>().single;
      expect(act.activity?.title, 'Slow Face Tracking');
    });

    test('a milestone naming an activity the doc never wrote shows it, without a link', () {
      final d = ppPhaseDocFor(15)!;
      final emo = d.milestoneFor(PpDocDomain.emotional)!;
      expect(emo.activities, contains('Naming All the Feelings'));
      expect(ppDocActivityNamed(d, 'Naming All the Feelings'), isNull);
    });
  });

  group('activities', () {
    test('every doc activity is in the pool, with no invented duration', () {
      final total = kPpPhaseDocList.fold<int>(0, (n, d) => n + d.activities.length);
      expect(kPhaseDocActivities, hasLength(total));
      final ids = kGrowActivities.map((a) => a.id).toSet();
      for (final a in kPhaseDocActivities) {
        expect(ids, contains(a.id));
        expect(a.minutes, 0);
        expect(a.timeLabel, 'At your pace');
        expect(a.fromPhaseDoc, isTrue);
      }
      expect(kPhaseDocActivities.map((a) => a.id).toSet(), hasLength(total), reason: 'ids are unique');
    });

    test('a newborn\'s pool leads with phase 1\'s activities, and they fit the age exactly', () {
      final pool = growActivitiesForAge(0);
      for (final a in kPhaseDocActivities.where((a) => a.id.startsWith('ph001_'))) {
        expect(pool.map((x) => x.id), contains(a.id));
        expect(growSuitsAge(a, 0), isTrue);
        expect(ppIsOwnPhaseDocActivity(a, 0), isTrue);
      }
      final ph2 = kPhaseDocActivities.firstWhere((a) => a.id.startsWith('ph002_'));
      expect(ppIsOwnPhaseDocActivity(ph2, 0), isFalse);
    });

    testWidgets('the activity screen draws the doc order', (tester) async {
      tester.view.physicalSize = const Size(400, 4000);
      tester.view.devicePixelRatio = 1.0;
      addTearDown(tester.view.reset);
      final a = kPhaseDocActivities.first;
      await tester.pumpWidget(MaterialApp(home: DevelopmentActivityScreen(activity: a)));
      await tester.pump();
      expect(tester.takeException(), isNull);
      expect(find.text(a.intro!), findsOneWidget);
      for (final h in ['What it builds', 'How to do it', 'Things to remember', 'Variations', 'The milestone it supports']) {
        expect(find.text(h), findsOneWidget, reason: h);
      }
      expect(find.text('At your pace'), findsOneWidget);
      expect(find.textContaining('0 min'), findsNothing);
    });
  });

  testWidgets('the phase map page: doc labels, no AAP caption over the doc snapshot, a way into the doc', (tester) async {
    tester.view.physicalSize = const Size(400, 5000);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.reset);
    await tester.pumpWidget(MaterialApp(home: PhaseDetailScreen(phase: kPhases.first)));
    await tester.pump();
    expect(tester.takeException(), isNull);
    expect(find.text('The Settling In'), findsOneWidget);
    expect(find.text('Living through this phase'), findsOneWidget);
    expect(find.text('Child snapshot'), findsOneWidget);
    expect(find.text('Nutrition'), findsOneWidget);
    expect(find.textContaining('three in four children'), findsNothing,
        reason: 'the doc snapshot is not the AAP 75% list');
    expect(find.byKey(const ValueKey('phase_detail_read_doc')), findsOneWidget);
  });

  test('wired: home, phase read and messages reach the docs', () {
    String src(String p) => File(p).readAsStringSync();
    expect(src('lib/screens/post_pregnancy/pp_phases_data.dart'), contains('ppPhaseWithDoc(ph).filledFor(c)'));
    expect(src('lib/screens/post_pregnancy/pp_phase_film.dart'), contains('ppOpenPhaseDocRead(context, doc, phase)'));
    expect(src('lib/screens/post_pregnancy/pp_home_v3.dart'), contains('ppOpenMilestoneRead(context, doc, page)'));
    expect(src('lib/screens/post_pregnancy/pp_grow_data.dart'), contains('...kPhaseDocActivities'));
    expect(src('lib/screens/post_pregnancy/pp_home_activities_store.dart'), contains('ppIsOwnPhaseDocActivity'));
    expect(src('lib/services/pp_messages_store.dart'), contains('ppPhaseWithDoc(p).name'));
  });
}
